def order_by_points(nums):
    def digit_sum(num):
        return sum(map(int, str(num).split()))[0]

    def index_sort(nums):
        for i, num in enumerate(nums):
            yield (digit_sum(num), -i)  # Sort by digits and original index
        yield (num,)  # Sort by number itself
    return list(index_sort(nums))

